package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethodMap;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector.MixInResolver;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Test class for _addMethodMixIns in AnnotatedClass.
 * Since the method is protected, we use a spy or a subclass to access it.
 */
public class AnnotatedClass__addMethodMixIns_TriageGen2Test {

    // Mock classes for testing reflection
    public static class TargetClass {
        public void existingMethod() {}
    }

    public static class MixInClass {
        public void mixInMethod() {}
        private void privateMethod() {} // Should be filtered by _isIncludableMemberMethod
    }

    // Subclass to expose the protected method for testing
    private static class TestableAnnotatedClass extends AnnotatedClass {
        protected TestableAnnotatedClass(Class<?> cls, com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr, com.fasterxml.jackson.databind.introspect.MixInResolver mir) {
            super(cls, aintr, mir);
        }

        @Override
        public void _addMethodMixIns(Class<?> targetClass, AnnotatedMethodMap methods, Class<?> mixInCls, AnnotatedMethodMap mixIns) {
            super._addMethodMixIns(targetClass, methods, mixInCls, mixIns);
        }
    }

    @Test
    public void test_addMethodMixIns_Case1_MixinMethodFoundInTarget() throws Exception {
        // Setup: Mixin method exists in the target class (am != null)
        AnnotatedClass annotatedClass = spy(AnnotatedClass.construct(TargetClass.class, 
                com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.noop(), 
                com.fasterxml.jackson.databind.introspect.MixInResolver.noMixIn()));

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        Method mixInMethod = MixInClass.class.getMethod("mixInMethod");
        AnnotatedMethod am = mock(AnnotatedMethod.class);

        // Mock behavior: find returns an existing method (meaning mix-under)
        when(methods.find(mixInMethod)).thenReturn(am);
        // Mock behavior: find returns null (meaning mix-in)
        when(methods.find(not(eq(mixInMethod)))).thenReturn(null);

        // We need to ensure _isIncludableMemberMethod returns true for our test method
        // Since we can't easily mock protected methods of the object under test without more spying,
        // we use public methods in our test classes.

        doCallRealMethod().when(annotatedClass)._addMethodMixIns(any(), any(), any(), any());
        doCallRealMethod().when(annotatedClass)._isIncludableMemberMethod(any());
        doCallRealMethod().when(annotatedClass)._constructMethod(any());
        doCallRealMethod().when(annotatedClass)._addMixUnders(any(), any());

        // Execute
        annotatedClass._addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // Verify _addMixUnders was called because am != null
        verify(annotatedClass)._addMixUnders(eq(mixInMethod), eq(am));
        // Verify _constructMethod was NOT called for this method
        verify(annotatedClass, never())._constructMethod(mixInMethod);
    }

    @Test
    public void test_addMethodMixIns_Case2_MixinMethodNotPresentInTarget() throws Exception {
        // Setup: Mixin method does NOT exist in target class (am == null)
        AnnotatedClass annotatedClass = spy(AnnotatedClass.construct(TargetClass.class, 
                com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.noop(), 
                com.fasterxml.jackson.databind.introspect.MixInResolver.noMixIn()));

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        Method mixInMethod = MixInClass.class.getMethod("mixInMethod");
        AnnotatedMethod amConstructed = mock(AnnotatedMethod.class);

        // Mock behavior: find returns null
        when(methods.find(mixInMethod)).thenReturn(null);

        doCallRealMethod().when(annotatedClass)._addMethodMixIns(any(), any(), any(), any());
        doCallRealMethod().when(annotatedClass)._isIncludableMemberMethod(any());
        doCallRealMethod().when(annotatedClass)._constructMethod(any());

        // Execute
        annotatedClass._addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // Verify _constructMethod was called and result added to mixIns
        verify(annotatedClass)._constructMethod(mixInMethod);
        verify(mixIns).add(amConstructed); // Note: in real code, _constructMethod returns this
        // Since we can't easily control the return of the real _constructMethod in this spy setup 
        // without more complex mocking, we verify the interaction.
        verify(annotatedClass)._constructMethod(mixInMethod);
    }

    @Test
    public void test_addMethodMixIns_FiltersIncludableMethods() throws Exception {
        // Setup: Test that _isIncludableMemberMethod is checked
        AnnotatedClass annotatedClass = spy(AnnotatedClass.construct(TargetClass.class, 
                com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.noop(), 
                com.fasterxml.jackson.databind.introspect.MixInResolver.noMixIn()));

        AnnotatedMethodMap methods = mock(AnnotatedMethodMap.class);
        AnnotatedMethodMap mixIns = mock(AnnotatedMethodMap.class);

        Method privateMethod = MixInClass.class.getDeclaredMethod("privateMethod");

        doCallRealMethod().when(annotatedClass)._addMethodMixIns(any(), any(), any(), any());
        // Mock _isIncludableMemberMethod to return false for private method
        when(annotatedClass._isIncludableMemberMethod(privateMethod)).thenReturn(false);

        // Execute
        annotatedClass._addMethodMixIns(TargetClass.class, methods, MixInClass.class, mixIns);

        // Verify find was never called for the excluded method
        verify(methods, never()).find(privateMethod);
    }
}
